export function greet(name: string, excited = false) {
  const message = `Hello, ${name}`;
  return excited ? `${message}!` : message;
}

export async function greet(name: string, excited = false) {
  const user = await fetchUser(name);
  const message = `Hello, ${user.displayName}`;
  return excited ? `${message}!` : message;
}
